package com.erudit.content;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import com.erudit.content.model.ContentItem;import com.erudit.content.service.LocalQuizCardGenerator;import com.erudit.integration.InternalClients.AiClient;import com.erudit.integration.InternalContracts.*;import io.github.resilience4j.circuitbreaker.CircuitBreakerRegistry;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.ObjectProvider;
class AiQuizCardGeneratorTest {@Test void usesAiAndFallsBackOnFailureOrMalformedPayload(){var provider=mock(ObjectProvider.class);var ai=mock(AiClient.class);when(provider.getIfAvailable()).thenReturn(ai);var generator=new LocalQuizCardGenerator(provider,CircuitBreakerRegistry.ofDefaults());var item=new ContentItem(UUID.randomUUID(),UUID.randomUUID(),"ARTICLE","Title","Description","Local fact.",null,"BEGINNER",1,false,"PUBLISHED",List.of(),Instant.now());doReturn(new AiCard("AI title","AI summary")).when(ai).card(any());assertThat(generator.generate(item).getFirst().question()).isEqualTo("AI title");doThrow(new IllegalStateException()).when(ai).card(any());assertThat(generator.generate(item).getFirst().fact()).isEqualTo("Local fact.");doReturn(new AiCard("","")).when(ai).card(any());assertThat(generator.generate(item).getFirst().fact()).isEqualTo("Local fact.");}}
